//! PRD-mcphost-resource-listing-shape-in-contract
//! AC1 (P0) — Given `RESOURCE_TEMPLATES`, When `mcphost contract dump` runs,
//! Then `contracts/host-tools.v1.json` carries a top-level `resources` object
//! with `uri_scheme` and `name_field`, each keyed by every template kind,
//! generated by iterating the registry.

use mcphost::api_contract::dump_contract;
use mcphost::kinds::KindRegistry;
use mcphost::resources::{RESOURCE_TEMPLATES, contract_section};
use serde_json::Value;
use std::collections::BTreeSet;
use std::process::Command;

const COMMITTED: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/contracts/host-tools.v1.json");

fn keys(v: &Value) -> BTreeSet<String> {
    v.as_object().expect("object").keys().cloned().collect()
}

#[test]
fn mcphost_resource_listing_shape_in_contract_ac01_committed_and_dumped_resources_are_keyed_by_every_kind() {
    let kinds: BTreeSet<String> = RESOURCE_TEMPLATES.iter().map(|t| t.kind.key().to_string()).collect();
    assert_eq!(kinds.len(), RESOURCE_TEMPLATES.len(), "one key per template row");

    let committed: Value = serde_json::from_slice(&std::fs::read(COMMITTED).unwrap()).unwrap();
    let dumped = dump_contract(&KindRegistry::with_builtin());
    for (label, doc) in [("committed", &committed), ("dumped", &dumped)] {
        let resources = &doc["resources"];
        assert!(resources.is_object(), "{label} contract has a top-level resources object");
        for field in ["uri_scheme", "name_field"] {
            assert_eq!(keys(&resources[field]), kinds, "{label} resources.{field} is keyed by every template kind");
        }
    }
    assert_eq!(
        dumped["resources"],
        contract_section(RESOURCE_TEMPLATES),
        "the dump's section is the registry rendered"
    );
}

#[test]
fn mcphost_resource_listing_shape_in_contract_ac01_dump_binary_agrees_with_committed_file() {
    let out = Command::new(env!("CARGO_BIN_EXE_mcphost"))
        .args(["contract", "dump", "--check", "--path", COMMITTED])
        .output()
        .expect("run mcphost contract dump --check");
    assert!(out.status.success(), "committed file is what the binary dumps: {}", String::from_utf8_lossy(&out.stderr));
}
